 1\ncagr = (ending_value / beginning_value) ** (1/n) - 1\n\nprint(f\"CAGR = (35810 / 135030)^(1/8) - 1\")\nprint(f\"CAGR = {(ending_value / beginning_value):.6f}^0.125 - 1\")\nprint(f\"CAGR = {cagr:.6f}\")\nprint(f\"CAGR rounded to 3 decimals: {round(cagr, 3)}\")\n\n# Annual decay factor = 1 + CAGR (since CAGR is negative, this is the decay factor)\nannual_decay_factor = 1 + cagr\nprint(f\"\\nAnnual decay factor = 1 + CAGR = 1 + {cagr:.6f} = {annual_decay_factor:.6f}\")\nprint(f\"Annual decay factor rounded to 3 decimals: {round(annual_decay_factor, 3)}\")\n\n# Arc elasticity using midpoint percentage change formula\n# Arc elasticity = (percentage change in value) / (percentage change in time)\n# Using midpoint method: % change = (new - old) / ((new + old)/2)\n\nt1 = 0  # Year 0 (FY 2011)\nt2 = 8  # Year 8 (FY 2019)\n\n# Midpoint percentage change in value\npct_change_value = (ending_value - beginning_value) / ((ending_value + beginning_value) / 2)\n\n# Midpoint percentage change in time\npct_change_time = (t2 - t1) / ((t2 + t1) / 2)\n\nprint(f\"\\nMidpoint percentage change in value: ({ending_value} - {beginning_value}) / (({ending_value} + {beginning_value})/2)\")\nprint(f\"= {ending_value - beginning_value} / {(ending_value + beginning_value) / 2:.2f}\")\nprint(f\"= {pct_change_value:.6f}\")\n\nprint(f\"\\nMidpoint percentage change in time: ({t2} - {t1}) / (({t2} + {t1})/2)\")\nprint(f\"= {t2 - t1} / {(t2 + t1) / 2:.2f}\")\nprint(f\"= {pct_change_time:.6f}\")\n\n# Arc elasticity\narc_elasticity = pct_change_value / pct_change_time\nprint(f\"\\nArc elasticity = {pct_change_value:.6f} / {pct_change_time:.6f} = {arc_elasticity:.6f}\")\nprint(f\"Arc elasticity rounded to 3 decimals: {round(arc_elasticity, 3)}\")\n\n# Final answer\nprint(f\"\\n=== FINAL ANSWER ===\")\ncagr_rounded = round(cagr, 3)\ndecay_rounded = round(annual_decay_factor, 3)\nelasticity_rounded = round(arc_elasticity, 3)\n\nprint(f\"[{cagr_rounded}, {decay_rounded}, {elasticity_rounded}]\")\n\nEOF"